Add functions that analyze the student data:

```python
def get_stats(students):
    """Calculate overall statistics."""
    if not students:
        return None

    fees = [s["Fee"] for s in students]
    marks = [s["Marks"] for s in students]

    return {
        "total_students": len(students),
        "total_fees": sum(fees),
        "average_fee": sum(fees) / len(fees),
        "average_marks": sum(marks) / len(marks),
        "topper": max(students, key=lambda s: s["Marks"]),
        "lowest": min(students, key=lambda s: s["Marks"]),
    }


def group_by_city(students):
    """Group students by city."""
    cities = {}
    for s in students:
        city = s["City"]
        if city not in cities:
            cities[city] = []
        cities[city].append(s["Name"])
    return cities


def group_by_course(students):
    """Group students by course with fee totals."""
    courses = {}
    for s in students:
        course = s["Course"]
        if course not in courses:
            courses[course] = {"count": 0, "total_fee": 0, "students": []}
        courses[course]["count"] += 1
        courses[course]["total_fee"] += s["Fee"]
        courses[course]["students"].append(s["Name"])
    return courses
```

