```python
def display_students(students):
    """Display students in a formatted table."""
    print(f"\n{'Name':<20} {'City':<12} {'Course':<20} {'Fee':>8} {'Marks':>6}")
    print("-" * 70)
    for s in students:
        print(f"{s['Name']:<20} {s['City']:<12} {s['Course']:<20} ₹{s['Fee']:>6,} {s['Marks']:>5}")
    print("-" * 70)


def main():
    """Main program loop."""
    # Ensure sample data exists
    if not os.path.exists("students.csv"):
        create_sample_data()

    students = load_students()

    while True:
        print("\n===== TechPath Student Manager =====")
        print("1. View all students")
        print("2. View statistics")
        print("3. View by city")
        print("4. View by course")
        print("5. Save text report")
        print("6. Save JSON report")
        print("7. Exit")

        choice = input("\nEnter your choice (1-7): ").strip()

        if choice == "1":
            display_students(students)
        elif choice == "2":
            stats = get_stats(students)
            print(f"\nTotal Students: {stats['total_students']}")
            print(f"Total Fees: ₹{stats['total_fees']:,}")
            print(f"Average Marks: {stats['average_marks']:.1f}")
            print(f"Topper: {stats['topper']['Name']} ({stats['topper']['Marks']})")
        elif choice == "3":
            for city, names in group_by_city(students).items():
                print(f"\n{city}: {', '.join(names)}")
        elif choice == "4":
            for course, data in group_by_course(students).items():
                print(f"\n{course}: {data['count']} students, ₹{data['total_fee']:,}")
        elif choice == "5":
            save_text_report(students)
        elif choice == "6":
            save_json_report(students)
        elif choice == "7":
            print("Goodbye! Thank you for using TechPath Student Manager.")
            break
        else:
            print("Invalid choice! Please enter 1-7.")


if __name__ == "__main__":
    main()
```

